const config = $('Datos del correo').first().json;
const para = String(config.correoProfesor || '').trim();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(para)) {
  throw new Error('Completa correoProfesor en el nodo Datos del correo antes de enviar.');
}
const productos = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
if (!productos.length || productos.some(p => !Number.isInteger(p.id) || typeof p.nombre !== 'string')) {
  throw new Error('La API no devolvió un catálogo de productos válido. No se enviará el correo.');
}
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const alumno = String(config.alumno || 'Adrian Tapia');
const grupo = String(config.grupo || '602');
const url = 'https://api-productos-adrian-lqwk.onrender.com/api/productos';
const filas = productos.map(p => `<tr><td style="padding:8px;border:1px solid #ccc">${p.id}</td><td style="padding:8px;border:1px solid #ccc">${esc(p.nombre)}</td></tr>`).join('');
const html = `<p>Buen día, profesor:</p><p>Comparto mi API de productos desarrollada en Node.js con PostgreSQL, desplegada en Render y consultada desde este flujo de n8n.</p><p><strong>Alumno:</strong> ${esc(alumno)}<br><strong>Grupo:</strong> ${esc(grupo)}</p><p><a href="${url}">Consultar la API de productos</a></p><p>Productos obtenidos de la API: <strong>${productos.length}</strong>.</p><table style="border-collapse:collapse"><thead><tr><th style="padding:8px;border:1px solid #ccc">ID</th><th style="padding:8px;border:1px solid #ccc">Producto</th></tr></thead><tbody>${filas}</tbody></table><p>Saludos,<br>${esc(alumno)}</p>`;
return [{json: {para, asunto: `Entrega API de productos - ${alumno} - Grupo ${grupo}`, html, totalProductos: productos.length, apiUrl: url}}];
